interface Greeter {
    String name();
    default String greet() { return "Hi " + name(); }
}
abstract class Member implements Greeter {
    protected int point;
    Member(int p) { point = p; }
    abstract int bonus();
    int total() { return point + bonus(); }
}
class Gold extends Member {
    Gold(int p) { super(p); }
    public String name() { return "Gold"; }
    int bonus() { return point / 2; }
    public String greet() { return "[" + name() + "]"; }
}
class Silver extends Member {
    Silver(int p) { super(p); }
    public String name() { return "Silver"; }
    int bonus() { return point > 100 ? 20 : 10; }
}
public class Main {
    public static void main(String[] args) {
        Member[] ms = { new Gold(90), new Silver(120), new Silver(40) };
        int sum = 0;
        for (Member m : ms) {
            System.out.println(m.greet() + ":" + m.total());
            sum += m.bonus();
        }
        System.out.println(sum);
    }
}

