public class Main {
    public static void main(String[] args) {
        int[][] a = { {1, 2, 3}, {4, 5, 6} };
        int[][] t = new int[a[0].length][a.length];
        for (int i = 0; i < a.length; i++)
            for (int j = 0; j < a[i].length; j++)
                t[j][i] = a[i][j] * (i + j);
        int diag = 0, rowMax = 0;
        String sep = "";
        for (int[] row : t) {
            int s = 0;
            for (int v : row) s += v;
            if (s > rowMax) rowMax = s;
            System.out.print(sep + s);
            sep = " ";
        }
        System.out.println();
        for (int i = 0; i < t.length && i < t[i].length; i++)
            diag += t[i][i];
        System.out.println(rowMax + " " + diag + " " + t.length + "x" + t[0].length);
    }
}

public class Main {
    static int cnt = 0;
    static boolean check(int v) {
        cnt++;
        return v % 2 == 0;
    }
    public static void main(String[] args) {
        int x = 7, y = 10;
        boolean r1 = check(x) && check(y);
        boolean r2 = check(x) & check(y);
        boolean r3 = check(y) || check(x);
        boolean r4 = check(y) | check(x);
        System.out.println(r1 + " " + r2 + " " + r3 + " " + r4 + " " + cnt);
        int a = 17, b = 5;
        a /= b;
        b += a * 2;
        int c = (a > b) ? a - b : b - a;
        c -= y / x * x;
        a <<= 2;
        char ch = 'a';
        ch += 2;
        int code = ch + 1;
        System.out.println(a + " " + b + " " + c + " " + ch + " " + code + " " + (char)(code - 2));
        x = (x & 1) == 1 ? x * 3 + 1 : x / 2;
        y = (y ^ x) % 7;
        System.out.println(x + " " + y);
    }
}

class Parent {
    String name = "Parent";
    static String kind() { return "P-static"; }
    String who() { return "P-who"; }
    String show() { return name + "/" + who(); }
}
class Child extends Parent {
    String name = "Child";
    static String kind() { return "C-static"; }
    String who() { return "C-who"; }
    String both() { return name + "+" + super.name; }
}
public class Main {
    public static void main(String[] args) {
        Parent p = new Child();
        Child c = (Child) p;
        System.out.println(p.name + " " + c.name);
        System.out.println(p.kind() + " " + c.kind());
        System.out.println(p.who() + " " + p.show());
        System.out.println(c.both() + " " + ((Parent) c).name.length());
    }
}

public class Main {
    static int score(String grade) {
        int s = 0;
        switch (grade) {
            case "A": s += 10;
            case "B": s += 5; break;
            case "C": s += 3;
            default: s += 1;
        }
        return s;
    }
    public static void main(String[] args) {
        String[] gs = { "B", "A", "C", "D", "A" };
        int total = 0;
        StringBuilder sb = new StringBuilder();
        for (String g : gs) {
            int v = score(g);
            total += v;
            sb.append(g).append(v);
        }
        System.out.println(sb + " " + total);
        int n = 0;
        for (int i = 1; i <= 5; i++) {
            switch (i % 3) {
                case 0: n += i;
                case 1: n += 1; break;
                case 2: n -= 1;
            }
        }
        System.out.println(n);
        char op = '*';
        int acc = 2;
        switch (op) {
            case '+': acc += 3; break;
            case '*': acc *= 3;
            case '-': acc -= 1;
            case '/': acc /= 2; break;
            default: acc = 0;
        }
        System.out.println(acc);
    }
}
